// Generate either a null pointer or a valid C-string and a safe length n.
// We constrain n to the available buffer size to avoid out-of-bounds reads.
int choose_null = (int)(*FUZZ_PARAM(unsigned int) % 2);
std::string buf = FUZZ_PARAM_STR();
const char *s = choose_null ? (const char *)0 : buf.c_str();
// When s is non-null, cap n to the string size. When s is null, pick a small n.
size_t n = 0;
if (s) {
    size_t sz = buf.size();
    // ensure at least 1 byte is testable, but allow n==0 as an edge case
    size_t add = (size_t)(*FUZZ_PARAM(unsigned int) % (sz + 1));
    n = add; // 0..size
} else {
    n = (size_t)(*FUZZ_PARAM(unsigned int) % 128u);
}
// Invoke the target function. We ignore the boolean result as the fuzzer explores both outcomes.
(void)simplejson_csnlen(s, n);
// No outputs

// Prepare an input buffer. To exercise both success and failure paths, sometimes use a valid JSON literal.
unsigned int choice = *FUZZ_PARAM(unsigned int);
std::string src;
switch (choice % 6u) {
    case 0: src = "null"; break;
    case 1: src = "true"; break;
    case 2: src = "123"; break;
    case 3: src = "\"str\""; break;
    case 4: src = "[]"; break;
    default: src = FUZZ_PARAM_STR(); break; // may be invalid JSON
}
// Call JSON::Parse; it may return nullptr on invalid input.
JSONValue *value = JSON::Parse(src.c_str());
if (!value) { FUZZ_BAIL(); }
// Provide the parsed tree as output; ownership is assumed by the fuzzer runtime.

// value must be a valid, non-null JSONValue tree. We rely on the pool providing a valid object.
// Call the target function to serialize the tree. Behavior on invalid nodes is library-defined.
std::string out = JSON::Stringify(value);
// Keep the input JSONValue alive by returning it as an output.
(void)out; // avoid unused warning

// Construct a JSON null value using the default constructor.
JSONValue *value = new JSONValue();
// Optionally annotate type for downstream stubs (not required by API).
FUZZ_SET_ATTR_STR(value, "kind", "null");
// Output the newly created value.

// Destroy the JSONValue. After this call, value must not be used.
delete value;
// No outputs; the object is destroyed.

// Invoke the predicate; object must be valid.
( void )value->IsNull();
// Return the object to the pool unchanged.

// Enforce precondition: must be string
if (!value->IsString()) { FUZZ_BAIL(); }
const std::string &s = value->AsString();
( void )s.size(); // light touch to use the reference
// Return the original object unchanged.

// Enforce precondition: must be array
if (!value->IsArray()) { FUZZ_BAIL(); }
const JSONArray &arr = value->AsArray();
( void )arr.size();

if (!value->IsObject()) { FUZZ_BAIL(); }
const JSONObject &obj = value->AsObject();
( void )obj.size();

// Disambiguate overloads based on the value type, enforcing preconditions.
if (value->IsArray()) {
    std::size_t count = value->CountChildren();
    // Choose an index that is in or just outside range to cover both outcomes.
    std::size_t pick = count ? (std::size_t)(*FUZZ_PARAM(unsigned int) % (count + 1)) : 0u;
    ( void )value->HasChild(pick);
} else if (value->IsObject()) {
    // Sometimes use an existing key, otherwise a random key.
    std::vector<std::string> keys = value->ObjectKeys();
    const char *name = nullptr;
    if (!keys.empty() && ((*FUZZ_PARAM(unsigned int) % 2u) == 0u)) {
        name = keys[(size_t)(*FUZZ_PARAM(unsigned int) % keys.size())].c_str();
    } else {
        std::string probe = FUZZ_PARAM_STR();
        name = probe.c_str();
    }
    ( void )value->HasChild(name);
} else {
    // Precondition violated for both overloads
    FUZZ_BAIL();
}
// Keep parent value alive.

// Exercise array and object child access with precondition checks.
if (value->IsArray()) {
    std::size_t count = value->CountChildren();
    if (count == 0u) { FUZZ_BAIL(); }
    std::size_t idx = (std::size_t)(*FUZZ_PARAM(unsigned int) % count);
    JSONValue *elem = value->Child(idx);
    ( void )elem; // Do not output child; lifetime is tied to parent.
} else if (value->IsObject()) {
    std::vector<std::string> keys = value->ObjectKeys();
    const char *name = nullptr;
    if (!keys.empty()) {
        name = keys[(size_t)(*FUZZ_PARAM(unsigned int) % keys.size())].c_str();
    } else {
        // If there are no keys, still exercise the function with a random key; may return nullptr.
        std::string probe = FUZZ_PARAM_STR();
        name = probe.c_str();
    }
    JSONValue *child = value->Child(name);
    ( void )child; // Not returned; avoid lifetime issues.
} else {
    FUZZ_BAIL();
}
// Return the original container value only.

// Only valid for object values.
if (!value->IsObject()) { FUZZ_BAIL(); }
std::vector<std::string> keys = value->ObjectKeys();
// Touch a few keys if present to increase coverage.
if (!keys.empty()) {
    (void)keys[ (size_t)(*FUZZ_PARAM(unsigned int) % keys.size()) ];
}
// Keep the object alive.

// Serialize this JSONValue with or without pretty printing to exercise both code paths.
bool pretty = ((*FUZZ_PARAM(unsigned int) % 2u) != 0u);
std::string out = value->Stringify(pretty);
// Basic sanity: Stringify should produce non-empty JSON for any valid value.
FUZZ_ASSERT(!out.empty(), "JSONValue::Stringify produced an empty string");
// Property check: the output of Stringify should be valid JSON that can be parsed.
JSONValue *round = JSON::Parse(out.c_str());
FUZZ_ASSERT(round != nullptr, "JSONValue::Stringify output was not parseable JSON");
// Clean up the parsed round-trip tree to avoid leaking allocations in this stub.
delete round;
// Keep the original value alive for further mutations by returning it as an output.
(void)out;

