import random
import json
import string
from typing import Any, List, Dict, Tuple

# This generator produces valid JSON text (UTF-8 bytes). We keep it under 4096 bytes and
# aim to cover diverse JSON types and edge cases to exercise parsing paths.

MAX_SIZE = 4096

def _rand_bool(r: random.Random) -> bool:
    return bool(r.getrandbits(1))

def _rand_int(r: random.Random) -> int:
    # Include small, large, negative, and boundary-like values
    choices = [0, 1, -1, 2**31-1, -2**31+1, 2**53-1, -(2**53-1)]
    if _rand_bool(r):
        choices.append(r.randint(-10**9, 10**9))
    return r.choice(choices)

def _rand_float(r: random.Random) -> float:
    # Avoid NaN/Inf; choose finite values and some with many decimals
    base = r.uniform(-1e6, 1e6)
    if r.random() < 0.3:
        base = r.choice([0.0, 1.0, -1.0, 1e-6, -1e-6, 1e6, -1e6, 3.141592653589793, 2.718281828459045])
    if r.random() < 0.7:
        base += r.random() * r.choice([1e-9, 1e-6, 1e-3, 1e-2])
    return float(base)

def _rand_ascii_printable(r: random.Random) -> str:
    return ''.join(r.choice(string.ascii_letters + string.digits + string.punctuation + ' ') for _ in range(r.randint(0, 16)))

def _rand_unicode(r: random.Random) -> str:
    ranges: List[Tuple[int,int]] = [
        (0x20, 0x7E),
        (0x00A0, 0x00FF),
        (0x0100, 0x017F),
        (0x0370, 0x03FF),
        (0x0400, 0x04FF),
        (0x2000, 0x206F),
        (0x2190, 0x21FF),
        (0x4E00, 0x9FFF),
        (0x1F300, 0x1F64F),
    ]
    length = r.randint(0, 12)
    out = []
    for _ in range(length):
        lo, hi = r.choice(ranges)
        cp = r.randint(lo, hi)
        if 0xD800 <= cp <= 0xDFFF:
            cp = 0xFFFD
        out.append(chr(cp))
    return ''.join(out)

def _rand_escape_sequence(r: random.Random) -> str:
    choices = ['\\"', '\\\\', '\\/', '\\b', '\\f', '\\n', '\\r', '\\t']
    if r.random() < 0.7:
        hexpart = ''.join(r.choice('0123456789abcdef') for _ in range(4))
        choices.append('\\u' + hexpart)
    return r.choice(choices)

def _rand_json_string(r: random.Random) -> str:
    parts: List[str] = []
    n = r.randint(0, 8)
    for _ in range(n):
        kind = r.randint(0, 4)
        if kind == 0:
            parts.append(_rand_ascii_printable(r))
        elif kind == 1:
            parts.append(_rand_unicode(r))
        elif kind == 2:
            parts.append(_rand_escape_sequence(r))
        elif kind == 3:
            parts.append(''.join(chr(r.randint(1, 31)) for _ in range(r.randint(0, 3))))
        else:
            parts.append('"')
    return ''.join(parts)

def _make_scalar(r: random.Random) -> Any:
    t = r.randint(0, 5)
    if t == 0:
        return None
    if t == 1:
        return _rand_json_string(r)
    if t == 2:
        return _rand_bool(r)
    if t == 3:
        if r.random() < 0.6:
            return _rand_int(r)
        return _rand_float(r)
    if t == 4:
        return _rand_int(r)
    return _rand_float(r)

def _make_array(r: random.Random, depth: int) -> List[Any]:
    length = r.randint(0, 8)
    arr: List[Any] = []
    for _ in range(length):
        arr.append(_make_value(r, depth + 1))
    return arr

def _unique_key(r: random.Random, existing: set) -> str:
    for _ in range(10):
        base = _rand_json_string(r)
        if base not in existing:
            return base
    i = 0
    while True:
        k = f"key_{i}_{r.randint(0, 9999)}"
        if k not in existing:
            return k
        i += 1

def _make_object(r: random.Random, depth: int) -> Dict[str, Any]:
    size = r.randint(0, 8)
    obj: Dict[str, Any] = {}
    keys = set()
    for _ in range(size):
        k = _unique_key(r, keys)
        keys.add(k)
        obj[k] = _make_value(r, depth + 1)
    return obj

def _make_value(r: random.Random, depth: int = 0) -> Any:
    if depth >= 4:
        return _make_scalar(r)
    choice = r.randint(0, 9)
    if choice <= 4:
        return _make_scalar(r)
    elif choice <= 6:
        return _make_array(r, depth)
    else:
        return _make_object(r, depth)

def _inject_whitespace(r: random.Random, s: str) -> str:
    # Insert optional leading/trailing whitespace and lightly intersperse inside
    if r.random() < 0.5:
        return s
    ws_options = [' ', '\t', '\n', '\r']
    lead = ''.join(r.choice(ws_options) for _ in range(r.randint(0, 8)))
    tail = ''.join(r.choice(ws_options) for _ in range(r.randint(0, 8)))
    s2 = lead + s + tail

    # Manually rebuild with optional spaces around commas/colons without breaking JSON
    def spaced_commas(text: str) -> str:
        parts = text.split(',')
        if len(parts) == 1:
            return text
        out = []
        for i, p in enumerate(parts):
            out.append(p)
            if i != len(parts) - 1:
                out.append(', ' if r.random() < 0.5 else ',')
        return ''.join(out)

    def spaced_colons(text: str) -> str:
        parts = text.split(':')
        if len(parts) == 1:
            return text
        out = []
        for i, p in enumerate(parts):
            out.append(p)
            if i != len(parts) - 1:
                out.append(' : ' if r.random() < 0.5 else ':')
        return ''.join(out)

    if r.random() < 0.6:
        s2 = spaced_commas(s2)
    if r.random() < 0.6:
        s2 = spaced_colons(s2)
    return s2

def _choose_top_level(r: random.Random) -> Any:
    m = r.randint(0, 7)
    if m == 0:
        return None
    if m == 1:
        return True if r.random() < 0.5 else False
    if m == 2:
        return _rand_json_string(r)
    if m == 3:
        return _rand_int(r) if r.random() < 0.5 else _rand_float(r)
    if m == 4:
        return _make_array(r, 0)
    if m == 5:
        return _make_object(r, 0)
    if m == 6:
        return [_make_value(r, 0), _make_value(r, 0), _make_value(r, 0)]
    return {"a": _make_value(r, 0), "b": _make_value(r, 0)}

def _ensure_size(s: str) -> str:
    if len(s.encode('utf-8')) <= MAX_SIZE:
        return s
    fallback_candidates = ["null", "true", "false", json.dumps(0), json.dumps(""), json.dumps("x"*16)]
    for c in fallback_candidates:
        if len(c.encode('utf-8')) <= MAX_SIZE:
            return c
    return "null"

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    value = _choose_top_level(r)

    if r.random() < 0.3:
        txt = json.dumps(value, ensure_ascii=True, separators=(",", ":"))
    elif r.random() < 0.6:
        txt = json.dumps(value, ensure_ascii=False)
    else:
        txt = json.dumps(value, ensure_ascii=True, indent=2)

    txt = _inject_whitespace(r, txt)
    txt = _ensure_size(txt)

    data = txt.encode('utf-8')
    if len(data) > MAX_SIZE:
        data = data[:MAX_SIZE]
    return data
